using Astronomy.MediaFactory.Core.KnowledgeFoundation;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.Query; using Xunit;
namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Query;
public sealed class AstronomyKnowledgeStatusFilterTests{[Fact]public void Constructs_and_normalizes(){var caller=new List<KnowledgeFoundationStatus>{KnowledgeFoundationStatus.Draft,KnowledgeFoundationStatus.Approved,KnowledgeFoundationStatus.Approved};var f=new AstronomyKnowledgeStatusFilter(caller);caller.Add(KnowledgeFoundationStatus.Draft);Assert.Equal(AstronomyKnowledgeQueryMatchMode.Any,f.MatchMode);Assert.Equal(new[]{KnowledgeFoundationStatus.Approved,KnowledgeFoundationStatus.Draft},f.Values);Assert.Throws<NotSupportedException>(()=>((IList<KnowledgeFoundationStatus>)f.Values).Add(KnowledgeFoundationStatus.Approved));}[Fact]public void Supports_all_mode(){var f=new AstronomyKnowledgeStatusFilter([KnowledgeFoundationStatus.Approved],AstronomyKnowledgeQueryMatchMode.All);Assert.Equal(AstronomyKnowledgeQueryMatchMode.All,f.MatchMode);}[Fact]public void Rejects_invalid_inputs(){Assert.Throws<ArgumentException>(()=>new AstronomyKnowledgeStatusFilter([]));Assert.Throws<ArgumentOutOfRangeException>(()=>new AstronomyKnowledgeStatusFilter([(KnowledgeFoundationStatus)99]));Assert.Throws<ArgumentOutOfRangeException>(()=>new AstronomyKnowledgeStatusFilter([KnowledgeFoundationStatus.Approved],(AstronomyKnowledgeQueryMatchMode)99));}}
